    assert out["reruns"] == ["Aria", "Dialyn", "Ukinami Yuzuha", "Asaba Harumasa"]
    # the sibling '====W-Engine Channels====' section never leaks in
    assert not any("Signal Search" in n for n in out["phase1"] + out["phase2"])


